"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[3151],{12(a){a.exports=JSON.parse('{"tag":{"label":"Graphs","permalink":"/concepts/tags/graphs","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"state-space-search-and-optimization/backtracking","title":"Backtracking","description":"Backtracking is an algorithmic paradigm used to solve problems in which the number of possible candidate solutions is very large, but many of those candidates can be discarded early because they violate some constraint. The central idea is simple: construct a solution step by step, and as soon as a partial solution cannot possibly lead to a valid complete solution, abandon it and return to the previous step.","permalink":"/concepts/state-space-search-and-optimization/backtracking"},{"id":"foundations-of-algorithms/data-structures","title":"Data Structures","description":"In the previous lessons we saw that the efficiency of a solution depends on the strategy we choose. It also depends, just as much, on how the data is organised in memory. The maximum pairwise product already gave us a hint: the same algorithm used several times more memory with a List than with an int[].","permalink":"/concepts/foundations-of-algorithms/data-structures"}],"unlisted":false}}')}}]);